package com.project.entity.enterprise;
import com.project.entity.Employee; import javax.persistence.*; import java.time.LocalDateTime;
@Entity @Table(name="approval_requests") public class ApprovalRequest { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.EAGER) @JoinColumn(name="employee_id",nullable=false) private Employee employee; private String requestType; private String referenceId; private String currentLevel="MANAGER"; private String status="PENDING"; @Column(length=1000) private String comments; private LocalDateTime createdAt=LocalDateTime.now(); private LocalDateTime updatedAt=LocalDateTime.now(); public Long getId(){return id;} public Employee getEmployee(){return employee;} public void setEmployee(Employee v){employee=v;} public String getRequestType(){return requestType;} public void setRequestType(String v){requestType=v;} public String getReferenceId(){return referenceId;} public void setReferenceId(String v){referenceId=v;} public String getCurrentLevel(){return currentLevel;} public void setCurrentLevel(String v){currentLevel=v;} public String getStatus(){return status;} public void setStatus(String v){status=v;} public String getComments(){return comments;} public void setComments(String v){comments=v;} public LocalDateTime getCreatedAt(){return createdAt;} public LocalDateTime getUpdatedAt(){return updatedAt;} }
